@startuml

class Machine {
  + serialNumber : string
  + make : string
  + model : string
  + purchaseDate : date
}

class Worker {
  + firstName : string
  + lastName : string
  + birthDate : date
  + address : string
  + skills : string[]
}

class ProductType {
  + material : string
  + weight : float
}

class Product {
  + name : string
}

class Client {
  + name : string
  + address : string
  + phoneNumber : string
  + contactPerson : string
}

class PurchaseOrder {
  + orderNumber : int
  + dateMade : date
  + expectedDeliveryDate : date
  + actualDeliveryDate : date
}

class OrderLine {
  + quantity : int
}

Machine "*" -- "*" Worker : operatedBy
Machine "1" -- "*" ProductType : produces
ProductType "1" -- "*" Product : isType
Client "1" -- "*" PurchaseOrder : issues
PurchaseOrder "1" -- "*" OrderLine : contains
OrderLine "*" -- "1" Product : refersTo

@enduml

